"""Locked scoring harness — do not edit this file.

Your pipeline function must have the signature:

    def answer_question(question: str) -> dict:
        ...
        return {"answer": "<string>", "citations": ["<doc_id>", ...]}

`citations` should list the doc_id(s) (see data/corpus.json) your pipeline
retrieved from to produce the answer. Call `run_hidden_eval(answer_question)`
from the notebook to score against the held-out question set.

Reports two independent scores, not combined into one:
  - `score`         (higher is better)      — answer correctness + citation accuracy
  - `total_tokens`  (lower is more frugal)  — tokens spent answering the whole set,
                                              read from rag.llm's usage counter

`total_tokens` is None if rag/llm.py no longer exposes reset_usage()/get_usage()
(e.g. you rewrote it from scratch without keeping the usage-tracking calls).
"""

import json
import time
from pathlib import Path
from typing import Callable

from eval.metrics import exact_match_score, f1_score

ROOT = Path(__file__).resolve().parent.parent
TEST_QA_PATH = ROOT / "eval" / "test_qa.json"


def _reset_token_tracking() -> None:
    try:
        from rag.llm import reset_usage

        reset_usage()
    except ImportError:
        pass


def _read_token_usage() -> dict | None:
    try:
        from rag.llm import get_usage

        return get_usage()
    except ImportError:
        return None


def run_hidden_eval(
    answer_fn: Callable[[str], dict],
    verbose: bool = True,
) -> dict:
    test_qa = json.loads(TEST_QA_PATH.read_text())
    _reset_token_tracking()

    em_total = 0.0
    f1_total = 0.0
    citation_hits = 0
    errors = 0
    start = time.time()

    for i, item in enumerate(test_qa):
        try:
            result = answer_fn(item["question"])
            answer = str(result.get("answer", ""))
            citations = result.get("citations", []) or []
        except Exception as exc:  # noqa: BLE001 - a broken pipeline just scores 0 on that item
            answer, citations = "", []
            errors += 1
            if verbose:
                print(f"  [{i + 1}/{len(test_qa)}] pipeline error: {exc}")

        em_total += exact_match_score(answer, item["answers"])
        f1_total += f1_score(answer, item["answers"])
        if item["doc_id"] in citations:
            citation_hits += 1

        if verbose and (i + 1) % 10 == 0:
            print(f"  scored {i + 1}/{len(test_qa)}...")

    n = len(test_qa)
    elapsed = time.time() - start

    em = em_total / n
    f1 = f1_total / n
    citation_hit_rate = citation_hits / n
    # Composite score used for ranking: answer correctness weighted above
    # citation accuracy, per the challenge scoring rule.
    score = round(100 * (0.8 * f1 + 0.2 * citation_hit_rate), 2)

    usage = _read_token_usage()
    total_tokens = usage["input_tokens"] + usage["output_tokens"] if usage else None

    results = {
        "n_questions": n,
        "exact_match": round(em, 4),
        "f1": round(f1, 4),
        "citation_hit_rate": round(citation_hit_rate, 4),
        "score": score,
        "errors": errors,
        "total_time_sec": round(elapsed, 1),
        "avg_latency_sec": round(elapsed / n, 2),
        "total_tokens": total_tokens,
        "input_tokens": usage["input_tokens"] if usage else None,
        "output_tokens": usage["output_tokens"] if usage else None,
        "avg_tokens_per_question": round(total_tokens / n, 1) if total_tokens is not None else None,
    }

    if verbose:
        print("\n=== RESULT ===")
        print(f"  {'score (higher is better)':<32}: {results['score']}")
        print(f"  {'total_tokens (lower is more frugal)':<32}: {results['total_tokens']}")
        print("  ---")
        for k, v in results.items():
            if k in ("score", "total_tokens"):
                continue
            print(f"  {k:<32}: {v}")

    return results
